    data=json.loads((OUT/'measured_data_audit.json').read_text());part=json.loads((OUT/'partition_audit.json').read_text());source=json.loads((OUT/'K562_source_allele_audit.json').read_text());reuse=json.loads((OUT/'immutable_reuse_audit.json').read_text());registry=json.loads((OUT/'final_fit_registry.json').read_text());selection=json.loads((OUT/'development_selection.json').read_text());policy=json.loads((OUT/'uncertainty_policy.json').read_text());check=json.loads((OUT/'final_checkpoint_audit.json').read_text());scorer=json.loads((OUT/'scorer_smoke_audit.json').read_text());test=json.loads((OUT/'reserved_study_results.json').read_text());extra=json.loads((OUT/'reserved_additional_checks.json').read_text());delivery=json.loads((OUT/'local_delivery_receipt.json').read_text());lock=json.loads((OUT/'final_model_lock.json').read_text());started=json.loads((OUT/'final_test_evaluation_started.json').read_text());card=json.loads((OUT/'model_card.json').read_text());requirements=[]
